"""Narrative of report 17 (Milestone 10, round 2: the free-motion gap; ADR 0010 amendment). Result sections are filled
from runs/m10r2/metrics_test.json."""
import os as _os
from pathlib import Path

from experiments.d7_extras import LABELS, load
from experiments.d_report import add_best_classical, wins_table
from experiments.m10_extras import criterion_table, latency_table, torque_rate_table
from experiments.m10r2_extras import REPORT, free_motion_figure, press_band_table

LABELS.update({"pd_shared": "PD tuned on the tracking composite", "pd_shared_cap": "PD tuned on the cap composite", "pd_feedforward": "PD (tracking-tuned) + inverse-dynamics feedforward",
               "pd_shared_cap_feedforward": "PD (cap-tuned) + inverse-dynamics feedforward", "best_classical": "Best classical controller of the family", "oracle_pd": "Oracle around the PD (privileged ceiling)",
               "distill_v3_gain_ext": "Milestone 10 student (gravity base, 5 N teacher floor)",
               "pd_residual_v3_ff": "Residual on the feedforward PD (free-space base)", "distill_v3_r2_gain_ext": "Student of the feedforward residual (7 N floor)",
               "neural_torque_v3_ff": "Direct torque network (free-space base)", "distill_v3_r2_torque": "Student of the torque network (7 N floor)",
               "distill_v3_r2_two_teachers": "Two-teacher student (ideal-robot labels in free space, oracle in contact)"})
_metrics_path = Path(_os.environ.get("LLC_METRICS", "runs/m10r2/metrics_test.json"))
_data, _groups = load(_metrics_path) if _metrics_path.exists() else ({}, {})
for _g in _groups.values():
    add_best_classical(_g)
ORDER = ["best_classical", "pd_shared", "pd_shared_cap", "pd_feedforward", "pd_shared_cap_feedforward", "oracle_pd", "distill_v3_gain_ext", "pd_residual_v3_ff", "distill_v3_r2_gain_ext", "distill_v3_r2_two_teachers", "neural_torque_v3_ff", "distill_v3_r2_torque"]
METHODS = [(k, LABELS.get(k, k)) for k in ORDER if k in _groups.get("in_distribution", {})]
LEARNED = [k for k in ("distill_v3_gain_ext", "pd_residual_v3_ff", "distill_v3_r2_gain_ext", "distill_v3_r2_two_teachers", "neural_torque_v3_ff", "distill_v3_r2_torque") if k in _groups.get("in_distribution", {})]
_FIG_METHODS = [k for k in ("best_classical", "pd_feedforward", "distill_v3_gain_ext", "pd_residual_v3_ff", "distill_v3_r2_gain_ext", "distill_v3_r2_two_teachers", "neural_torque_v3_ff", "distill_v3_r2_torque") if k in _groups.get("in_distribution", {})]

CRITERION_SECTION = ("<h2>The success criterion</h2>\n<p>Every family and held-out group composite of each learned method against the best classical controller of that family (the lower cap composite among the two tuned PDs and their feedforward variants), as in report 15.</p>\n" + criterion_table(_groups, LEARNED)) if _groups else ""
FREE_SECTION = ("<h2>Free motion against contact</h2>\n" + free_motion_figure(_groups, _FIG_METHODS, "fig-free-motion")) if _groups else ""
WINS_SECTION = ("<h2>Where the learned controllers win and lose</h2>\n" + wins_table(_data, METHODS, "best_classical")) if _data else ""
PRESS_SECTION = ("<h2>The press band</h2>\n" + press_band_table(_groups, [k for k, _ in METHODS])) if _groups else ""
LATENCY_SECTION = ("<h2>Compute latency</h2>\n" + latency_table(_groups, LEARNED)) if _groups else ""
SMOOTH_SECTION = ("<h2>Smoothness</h2>\n" + torque_rate_table(_groups, [k for k, _ in METHODS])) if _groups else ""
_videos = REPORT / "data" / "videos.html"
VIDEO_SECTION = ("<h2>Representative episodes</h2>\n" + _videos.read_text()) if _videos.exists() else ""

NARRATIVE = {
    "question": """<p>Milestone 10 left one family to the classical side: free joint-space motion, where the PD with the inverse-dynamics feedforward of the reference tracks at 4.9 mrad and the distilled student at 11.9 (report 15). The learned controllers carried a gravity-only base, so the model term that makes the feedforward PD anticipate the reference had to be learned from the history. This round (ADR 0010, amendment 2) gives the learned controllers the same base, trains their free-space part on the free-space families only and selects it there, enforces the protocol's 7 N press floor in the teacher, and adds a direct torque network next to the PD residual. The question is whether the student now meets the criterion on every row without giving up what it won in contact.</p>""",
    "setup": """<p><strong>Bases, three seeds each.</strong> (i) A torque residual on the PD with the inverse-dynamics feedforward, tau = K_p e + K_d de + M(q) qdd_ref + C(q, qd_ref) qd_ref + g(q) + residual, trained by the actor-critic through the plant (the D3 recipe on the v3 tracking-tuned gains) on the hold, free, policy-like and step families only (the first two stages of the curriculum, 250 iterations), the checkpoint selected on the free-space cap composite of the validation split. (ii) A direct torque network with the same history input, warm-started by imitating the feedforward PD on closed-loop free-space windows of the analytic model, then trained by the same actor-critic at a tenfold smaller learning rate (at 1e-3 the first updates destroyed the warm start). The reference acceleration enters the training rollouts as a clipped central difference of the reference velocity.</p>
<p><strong>Students, three seeds each.</strong> Distilled by DAgger from the privileged contact-impedance oracle around the frozen base (the teacher), with the press floor raised from 5 N to the protocol's 7 N, twelve iterations of 48 episodes, the teacher driving in the first two, free-space decisions weighted three times in the label loss; the residual student in the gain-residual form with the external-torque input (as in Milestone 10), the torque student with the direct torque output and the external-torque input. The Milestone 10 student (gravity base, 5 N floor) stays in every table as the controller to beat.</p>
<p><strong>Two teachers (item D), three seeds.</strong> The same student recipe from the same residual bases, with the free-space families labelled by the ideal-robot torque of the TAM-style method instead of the oracle: at every decision of a student-driven episode, the torque the sampled plant needs to produce the nominal robot's acceleration under the nominal law (the student's PD base with its feedforward, without the learned part; the hold family's pulses enter as external loads the ideal robot also feels; decisions where the nominal law saturates an actuator or the correction exceeds 30 Nm are dropped), privileged in simulation; the contact families keep the oracle with the 7 N floor. A first form of these labels, taken under the student's full command as in the Milestone 10 ideal-robot run, is reported as a failure.</p>
<p><strong>Classical set and benchmark.</strong> As in report 15: the PD tuned on the tracking composite, the PD tuned on the cap composite, the feedforward variant of each, the best of the four per family as the reference of every comparison, the oracle around the tracking-tuned PD as the ceiling; protocol v3 with every held-out group, the two task families and the 5 ms latency group; the same pre-registered criterion (within 5% of the best classical or better on every family and group composite, better on the contact families and the task-success rates, three seeds, no divergence at 5 ms).</p>""",
    "extra_sections": [s for s in (CRITERION_SECTION, FREE_SECTION, WINS_SECTION, PRESS_SECTION, LATENCY_SECTION, SMOOTH_SECTION, VIDEO_SECTION) if s],
    "findings": """<ol>
<li><strong>The feedforward base closes most of the free-motion gap and costs nothing elsewhere.</strong> The student of the feedforward residual tracks free motion at 6.9 mrad in distribution against 11.9 for the Milestone 10 student and 4.9 for the feedforward PD; as cap-composite ratios to the best classical controller it is at 1.31 in distribution, 0.83 on the held-out workspace, 1.44 and 1.49 at the two speeds, 0.64 with the 3 kg payload and 1.24 on the instance deviations. It meets 29 of the 33 rows of the criterion (the Milestone 10 student 27); the four misses are free motion where the nominal feedforward is accurate enough for the PD. Hold 0.72 of the best classical (4.1 against 8.1 mrad), policy-like targets 0.97, steps 0.82.</li>
<li><strong>The remaining gap was the base's, not the student's.</strong> That student reproduces its base in free space to within 4 to 17% (free 0.47 against 0.43, hold 1.26 against 1.08): the free-space fix holds. The base itself, the actor-critic residual on the feedforward PD, tracks free motion at 6.9 mrad where the feedforward PD alone tracks at 4.9, while it is smoother (torque rate 89 against 115 Nm/s) and wins hold, policy-like and step targets: the training reward (a bounded position kernel of 20 mrad width plus a torque-rate penalty) does not distinguish 5 from 7 mrad. Selecting the base on free space moved its checkpoint but cannot create what the reward does not ask for.</li>
<li><strong>Two teachers close it: the ideal-robot labels in free space halve the feedforward PD's error.</strong> The two-teacher student tracks free motion at 2.6 mrad in distribution (seeds 2.6, 2.6, 2.7) against 4.9 for the feedforward PD, 2.9 against 9.5 on the held-out workspace, 3.7 and 6.2 against 5.7 and 8.3 at the two speeds, 5.0 against 20.6 with the 3 kg payload and 3.0 against 6.4 on the instance deviations; hold at 1.6 against 8.1 mrad. Its free-motion composites are 0.36 to 0.90 of the best classical in every group, hold 0.47, steps 0.79, and its contact families are those of the oracle-only student (press 4.49, blocked 5.05, task 3.28; compliant surfaces 0.40 to 0.60; payload group 0.51 to 0.68). It meets 28 of 33 rows: the five misses are all the policy-like family, at 1.05 to 1.06 of the best classical in every group (in distribution 2.47 against 2.34, with a lower tracking error, 40.6 against 43.1 mrad, and a higher torque rate, 159 against 115 Nm/s in free motion). The label matters in its reference: taken under the student's full command (the Milestone 10 form) the target drifts with the student's own residual and every iteration degraded hold and free motion (validation hold 0.77 to 2.1 to 3.8, free 0.37 to 0.8 to 3.5; runs distill_two_v0); taken under the nominal law the student converged in every seed (hold 0.77 to 0.5 to 0.8, free 0.37 to 0.24 to 0.31, blocked 17 to 4 to 5 on validation over twelve iterations).</li>
<li><strong>The 7 N floor moves the students into the press band at a price in excess force.</strong> On press-and-slide the round-2 students press with 10.6 to 11.8 N mean (the Milestone 10 student 6.1 N, below the floor; force below 7 N 1.0 to 1.2 against 3.0) and hold 5.0 to 5.4 N above the cap against 2.9; their press composites are 4.49 against 3.61 (0.87 of the best classical, which presses with 18 N and 9.1 N above the cap). Blocked targets 4.9 to 5.1 (0.47 of the best classical; 4.6 to 5.3 N above the cap, 64 N sustained peak, apparent stiffness 390 N/m, release reaction 0.2 s); the task family 3.2 to 3.3.</li>
<li><strong>Tasks: the first success win.</strong> Push success 52 to 54% for the round-2 students against 31% for every classical controller and the Milestone 10 student (box yaw 15 against 20 degrees), with the same 2 N object peak; place success 100% for all, the students placing at 5 to 6 N against 14 N and tracking the lift at 4.3 to 5.0 against 8.4 mrad. The task half of the criterion is met on pushing and tied at the ceiling on placing. Eight or nine of sixteen pushes against five is a small count; the paired interval is the evidence to read.</li>
<li><strong>A direct torque network is the wrong student.</strong> As a base it is the best hold tracker among the bases (3.0 against 8.1 mrad) and wins steps (2.30), loses free motion (15.4 mrad) and, untrained in contact, presses with 85 N. Its student fixes contact (blocked 4.24, press 4.11, the task family 3.26) and loses every free-space family (hold 3.14, free 3.10 at 22.9 mrad, policy-like 3.09, steps 3.67) with a torque rate of 1953 Nm/s in free motion: a torque held for 10 ms is open-loop for 10 ms, whereas the residual form keeps the 1 kHz PD underneath. At 5 ms of latency it degrades threefold (hold 11.2, free 9.8) where the residual students move by at most 5%. Twenty of 33 rows for the student, six for the base.</li>
<li><strong>Realism checks.</strong> No controller diverges in any group; the residual students' in-distribution composites move by at most 5% at 5 ms of latency (the two-teacher student's steps 2.61 to 2.74); their torque rate in free motion is above the stiff PD's (128 and 159 against 115 Nm/s) and higher in contact.</li>
</ol>""",
    "caveats": """<ul>
<li>The best classical controller is chosen per family on the test cases themselves; the learned controllers are selected once on the validation split.</li>
<li>The ideal-robot labels are privileged (the sampled plant's inverse dynamics) and exist only in simulation; on a real robot the same supervision would need a system identification or a learned plant model.</li>
<li>The torque network is a single architecture and training recipe (history input, warm start on the feedforward PD, actor-critic at 1e-4); its result is a statement about this recipe, not about direct torque policies in general.</li>
<li>The feedforward base uses the nominal model; on the held-out instance and payload groups it is as wrong as the feedforward PD's, so any advantage there is the learned part's.</li>
<li>Light sliding contact detaches on this plant for every controller (report 14); the contact-loss rate of the sliding families measures the simulator as much as the controller.</li>
<li>Three seeds per learned method; the oracle is privileged and a ceiling, not a baseline.</li>
</ul>""",
    "next": """<ul>
<li>The policy-like family is the two-teacher student's only miss, by 5 to 6%, with better tracking and a higher torque rate: the ideal labels are dropped where the nominal law saturates (target jumps), so the student's behaviour there is the base's; a smoothness term in the free-space labels, or the oracle's labels on that family only, would settle it.</li>
<li>Push success with more cases (the 16-case families leave 52 to 54 against 31% within a few boxes) before it enters a claim.</li>
<li>The press band versus the cap: the 7 N floor and the 15 N cap leave a 5 to 12 N window that the sliding families' detachments make hard to hold; the plant question of report 14 comes before further tuning of the teacher.</li>
<li>Checkpoint 2 is revised with the two-teacher student as the headline controller; the real robot (Milestone 7) remains unauthorised.</li>
</ul>""",
}
